-- KICD Kiswahili Grade 6 (2024) sourced structure; VibeSchool original outcomes.
-- Published KICD total 120; individually listed 53 allocations sum to 115.
-- Five clearly attributed VibeSchool review lessons bridge the planning total.
-- Preserve all earlier grade readers and the teacher-owned Scheme API.
-- authorization-test: public.grade6_kiswahili_reader_bindings
begin;
create table if not exists public.grade6_kiswahili_reader_bindings(
  source_ref text primary key,
  sub_strand_id uuid not null unique references public.cbc_strands(id) on delete restrict,
  source_url text not null,
  source_version text not null,
  key_inquiry_questions text[] not null default '{}',
  suggested_experiences text[] not null default '{}',
  source_suggested_lessons integer not null check(source_suggested_lessons>0),
  vibeschool_review_lessons integer not null default 0 check(vibeschool_review_lessons>=0),
  status text not null default 'active' check(status in('active','archived')),
  created_at timestamptz not null default now()
);
alter table public.grade6_kiswahili_reader_bindings enable row level security;
revoke all on public.grade6_kiswahili_reader_bindings from public,anon,authenticated;
grant select on public.grade6_kiswahili_reader_bindings to authenticated;
drop policy if exists grade6_kiswahili_bindings_read on public.grade6_kiswahili_reader_bindings;
create policy grade6_kiswahili_bindings_read on public.grade6_kiswahili_reader_bindings
  for select to authenticated using(status='active');

create temporary table _vs_grade6_sw_catalog(source_ref text primary key,unit jsonb not null) on commit drop;
insert into _vs_grade6_sw_catalog(source_ref,unit)
select 'VS-CUR-G06-SW-2026#'||(unit->>'id'),unit
from jsonb_array_elements('[{"id":"1.1.1","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Kusikiliza na Kuzungumza","title":"Matamshi Bora","persistedTitle":"Viungo vya Mwili vya Ndani — Matamshi Bora","sourceLessons":2,"supportLessons":1,"lessons":3,"outcomes":["Kutambua namna ya kutumia matamshi bora katika mazungumzo kuhusu viungo vya mwili vya ndani.","Kueleza ujumbe wa mzungumzaji kwa matamshi yanayoeleweka na maneno yanayofaa muktadha wa viungo vya mwili vya ndani.","Kushiriki mazungumzo au uwasilishaji mfupi kwa kusikiliza wengine na kutoa majibu yenye heshima."],"inquiry":["Je, stadi ya matamshi bora hutusaidiaje kuelewa na kueleza viungo vya mwili vya ndani?"],"experiences":["Sikiliza mazungumzo mafupi yaliyotungwa na mwalimu kuhusu viungo vya mwili vya ndani na ubainishe kauli muhimu.","Fanya mazoezi ya matamshi bora kwa jozi; mwezako atoe mrejesho wa heshima.","Wasilisha ujumbe wa sekunde 45 kwa darasa ukitumia msamiati unaohusiana na mada."],"resources":"Mazungumzo asilia, kadi za msamiati, sauti iliyorekodiwa na daftari.","assessment":"Orodha ya uchunguzi wa mazungumzo, matamshi, usikilizaji na majibu.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"1.2.1","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Kusoma","title":"Kusoma kwa Ufahamu","persistedTitle":"Viungo vya Mwili vya Ndani — Kusoma kwa Ufahamu","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kusoma matini inayohusu viungo vya mwili vya ndani kwa kutumia stadi ya kusoma kwa ufahamu.","Kubainisha msamiati, hoja kuu na maelezo muhimu yanayosaidia kuelewa matini.","Kujibu maswali na kueleza ujumbe wa matini kwa maneno yake mwenyewe na ushahidi wa alichosoma."],"inquiry":["Je, stadi ya kusoma kwa ufahamu hutusaidiaje kuelewa na kueleza viungo vya mwili vya ndani?"],"experiences":["Soma kifungu asilia kuhusu viungo vya mwili vya ndani, tia alama kwenye msamiati muhimu na ueleze maana.","Jibu maswali matatu ya ufahamu na utoe sababu kutoka kwenye kifungu.","Toa muhtasari wa hoja kuu kwa maneno yako mwenyewe."],"resources":"Vifungu asilia, kamusi ya mwanafunzi, vitabu vya darasa na daftari.","assessment":"Majibu ya ufahamu, msamiati na muhtasari unaotumia ushahidi wa matini.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"1.3.1","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Kuandika","title":"Insha ya Wasifu","persistedTitle":"Viungo vya Mwili vya Ndani — Insha ya Wasifu","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kupanga mawazo yanayohusu viungo vya mwili vya ndani kwa kufuata muundo wa insha ya wasifu.","Kuandika matini yenye mpangilio mzuri, msamiati sahihi na maelezo yanayolenga msomaji.","Kukagua tahajia, uakifishaji na mtiririko wa mawazo na kuboresha rasimu baada ya maoni."],"inquiry":["Je, stadi ya insha ya wasifu hutusaidiaje kuelewa na kueleza viungo vya mwili vya ndani?"],"experiences":["Panga mawazo kwa ramani fupi kabla ya kuandika insha ya wasifu kuhusu viungo vya mwili vya ndani.","Andika rasimu, isome kwa mwenzako na ubaini sehemu zinazohitaji kufafanuliwa.","Wasilisha toleo lililoboreshwa ukizingatia lengo, hadhira na kanuni za uandishi."],"resources":"Vichocheo vya uandishi, daftari, kielelezo asilia na orodha ya ukaguzi.","assessment":"Rubriki ya muundo, ubunifu, usahihi wa lugha na uhariri.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"1.4.1","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Sarufi","title":"Vivumishi vya Sifa","persistedTitle":"Viungo vya Mwili vya Ndani — Vivumishi vya Sifa","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya vivumishi vya sifa katika sentensi zinazohusiana na viungo vya mwili vya ndani.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vivumishi vya sifa na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vivumishi vya sifa na kueleza sababu ya marekebisho."],"inquiry":["Je, vivumishi vya sifa husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu viungo vya mwili vya ndani na utambue vivumishi vya sifa.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"1.4.2","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Sarufi","title":"Vivumishi Viashiria","persistedTitle":"Viungo vya Mwili vya Ndani — Vivumishi Viashiria (2)","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya vivumishi viashiria katika sentensi zinazohusiana na viungo vya mwili vya ndani.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vivumishi viashiria na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vivumishi viashiria na kueleza sababu ya marekebisho."],"inquiry":["Je, vivumishi viashiria husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu viungo vya mwili vya ndani na utambue vivumishi viashiria.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"1.4.3","themeId":1,"theme":"Viungo vya Mwili vya Ndani","strand":"Sarufi","title":"Vivumishi Vimilikishi","persistedTitle":"Viungo vya Mwili vya Ndani — Vivumishi Vimilikishi (3)","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya vivumishi vimilikishi katika sentensi zinazohusiana na viungo vya mwili vya ndani.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vivumishi vimilikishi na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vivumishi vimilikishi na kueleza sababu ya marekebisho."],"inquiry":["Je, vivumishi vimilikishi husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu viungo vya mwili vya ndani na utambue vivumishi vimilikishi.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.1.1","themeId":2,"theme":"Michezo","strand":"Kusikiliza na Kuzungumza","title":"Maamkuzi na Maagano","persistedTitle":"Michezo — Maamkuzi na Maagano","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua namna ya kutumia maamkuzi na maagano katika mazungumzo kuhusu michezo.","Kueleza ujumbe wa mzungumzaji kwa matamshi yanayoeleweka na maneno yanayofaa muktadha wa michezo.","Kushiriki mazungumzo au uwasilishaji mfupi kwa kusikiliza wengine na kutoa majibu yenye heshima."],"inquiry":["Je, stadi ya maamkuzi na maagano hutusaidiaje kuelewa na kueleza michezo?"],"experiences":["Sikiliza mazungumzo mafupi yaliyotungwa na mwalimu kuhusu michezo na ubainishe kauli muhimu.","Fanya mazoezi ya maamkuzi na maagano kwa jozi; mwezako atoe mrejesho wa heshima.","Wasilisha ujumbe wa sekunde 45 kwa darasa ukitumia msamiati unaohusiana na mada."],"resources":"Mazungumzo asilia, kadi za msamiati, sauti iliyorekodiwa na daftari.","assessment":"Orodha ya uchunguzi wa mazungumzo, matamshi, usikilizaji na majibu.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.2.1","themeId":2,"theme":"Michezo","strand":"Kusoma","title":"Kusoma kwa Kina","persistedTitle":"Michezo — Kusoma kwa Kina","sourceLessons":3,"supportLessons":0,"lessons":3,"outcomes":["Kusoma matini inayohusu michezo kwa kutumia stadi ya kusoma kwa kina.","Kubainisha msamiati, hoja kuu na maelezo muhimu yanayosaidia kuelewa matini.","Kujibu maswali na kueleza ujumbe wa matini kwa maneno yake mwenyewe na ushahidi wa alichosoma."],"inquiry":["Je, stadi ya kusoma kwa kina hutusaidiaje kuelewa na kueleza michezo?"],"experiences":["Soma kifungu asilia kuhusu michezo, tia alama kwenye msamiati muhimu na ueleze maana.","Jibu maswali matatu ya ufahamu na utoe sababu kutoka kwenye kifungu.","Toa muhtasari wa hoja kuu kwa maneno yako mwenyewe."],"resources":"Vifungu asilia, kamusi ya mwanafunzi, vitabu vya darasa na daftari.","assessment":"Majibu ya ufahamu, msamiati na muhtasari unaotumia ushahidi wa matini.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.3.1","themeId":2,"theme":"Michezo","strand":"Kuandika","title":"Insha ya Masimulizi","persistedTitle":"Michezo — Insha ya Masimulizi","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kupanga mawazo yanayohusu michezo kwa kufuata muundo wa insha ya masimulizi.","Kuandika matini yenye mpangilio mzuri, msamiati sahihi na maelezo yanayolenga msomaji.","Kukagua tahajia, uakifishaji na mtiririko wa mawazo na kuboresha rasimu baada ya maoni."],"inquiry":["Je, stadi ya insha ya masimulizi hutusaidiaje kuelewa na kueleza michezo?"],"experiences":["Panga mawazo kwa ramani fupi kabla ya kuandika insha ya masimulizi kuhusu michezo.","Andika rasimu, isome kwa mwenzako na ubaini sehemu zinazohitaji kufafanuliwa.","Wasilisha toleo lililoboreshwa ukizingatia lengo, hadhira na kanuni za uandishi."],"resources":"Vichocheo vya uandishi, daftari, kielelezo asilia na orodha ya ukaguzi.","assessment":"Rubriki ya muundo, ubunifu, usahihi wa lugha na uhariri.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.4.1","themeId":2,"theme":"Michezo","strand":"Sarufi","title":"Vivumishi vya Idadi","persistedTitle":"Michezo — Vivumishi vya Idadi","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya vivumishi vya idadi katika sentensi zinazohusiana na michezo.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vivumishi vya idadi na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vivumishi vya idadi na kueleza sababu ya marekebisho."],"inquiry":["Je, vivumishi vya idadi husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu michezo na utambue vivumishi vya idadi.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.4.2","themeId":2,"theme":"Michezo","strand":"Sarufi","title":"Vivumishi Viulizi","persistedTitle":"Michezo — Vivumishi Viulizi (2)","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya vivumishi viulizi katika sentensi zinazohusiana na michezo.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vivumishi viulizi na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vivumishi viulizi na kueleza sababu ya marekebisho."],"inquiry":["Je, vivumishi viulizi husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu michezo na utambue vivumishi viulizi.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"2.4.3","themeId":2,"theme":"Michezo","strand":"Sarufi","title":"Kivumishi Kielezi","persistedTitle":"Michezo — Kivumishi Kielezi","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya kivumishi kielezi katika sentensi zinazohusiana na michezo.","Kutunga sentensi sahihi kwa kuzingatia kanuni za kivumishi kielezi na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya kivumishi kielezi na kueleza sababu ya marekebisho."],"inquiry":["Je, kivumishi kielezi husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu michezo na utambue kivumishi kielezi.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"3.1.1","themeId":3,"theme":"Mahusiano","strand":"Kusikiliza na Kuzungumza","title":"Matamshi Bora","persistedTitle":"Mahusiano — Matamshi Bora","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua namna ya kutumia matamshi bora katika mazungumzo kuhusu mahusiano.","Kueleza ujumbe wa mzungumzaji kwa matamshi yanayoeleweka na maneno yanayofaa muktadha wa mahusiano.","Kushiriki mazungumzo au uwasilishaji mfupi kwa kusikiliza wengine na kutoa majibu yenye heshima."],"inquiry":["Je, stadi ya matamshi bora hutusaidiaje kuelewa na kueleza mahusiano?"],"experiences":["Sikiliza mazungumzo mafupi yaliyotungwa na mwalimu kuhusu mahusiano na ubainishe kauli muhimu.","Fanya mazoezi ya matamshi bora kwa jozi; mwezako atoe mrejesho wa heshima.","Wasilisha ujumbe wa sekunde 45 kwa darasa ukitumia msamiati unaohusia