:["Kutambua matumizi ya vinyume vya vivumishi katika sentensi zinazohusiana na afya ya akili.","Kutunga sentensi sahihi kwa kuzingatia kanuni za vinyume vya vivumishi na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya vinyume vya vivumishi na kueleza sababu ya marekebisho."],"inquiry":["Je, vinyume vya vivumishi husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu afya ya akili na utambue vinyume vya vivumishi.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"10.1.1","themeId":10,"theme":"Kukabiliana na Ugaidi","strand":"Kusikiliza na Kuzungumza","title":"Sitiara za Tabia","persistedTitle":"Kukabiliana na Ugaidi — Sitiara za Tabia","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua namna ya kutumia sitiara za tabia katika mazungumzo kuhusu kukabiliana na ugaidi.","Kueleza ujumbe wa mzungumzaji kwa matamshi yanayoeleweka na maneno yanayofaa muktadha wa kukabiliana na ugaidi.","Kushiriki mazungumzo au uwasilishaji mfupi kwa kusikiliza wengine na kutoa majibu yenye heshima."],"inquiry":["Je, stadi ya sitiara za tabia hutusaidiaje kuelewa na kueleza kukabiliana na ugaidi?"],"experiences":["Sikiliza mazungumzo mafupi yaliyotungwa na mwalimu kuhusu kukabiliana na ugaidi na ubainishe kauli muhimu.","Fanya mazoezi ya sitiara za tabia kwa jozi; mwezako atoe mrejesho wa heshima.","Wasilisha ujumbe wa sekunde 45 kwa darasa ukitumia msamiati unaohusiana na mada."],"resources":"Mazungumzo asilia, kadi za msamiati, sauti iliyorekodiwa na daftari.","assessment":"Orodha ya uchunguzi wa mazungumzo, matamshi, usikilizaji na majibu.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"10.2.1","themeId":10,"theme":"Kukabiliana na Ugaidi","strand":"Kusoma","title":"Kusoma kwa Mapana","persistedTitle":"Kukabiliana na Ugaidi — Kusoma kwa Mapana","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kusoma matini inayohusu kukabiliana na ugaidi kwa kutumia stadi ya kusoma kwa mapana.","Kubainisha msamiati, hoja kuu na maelezo muhimu yanayosaidia kuelewa matini.","Kujibu maswali na kueleza ujumbe wa matini kwa maneno yake mwenyewe na ushahidi wa alichosoma."],"inquiry":["Je, stadi ya kusoma kwa mapana hutusaidiaje kuelewa na kueleza kukabiliana na ugaidi?"],"experiences":["Soma kifungu asilia kuhusu kukabiliana na ugaidi, tia alama kwenye msamiati muhimu na ueleze maana.","Jibu maswali matatu ya ufahamu na utoe sababu kutoka kwenye kifungu.","Toa muhtasari wa hoja kuu kwa maneno yako mwenyewe."],"resources":"Vifungu asilia, kamusi ya mwanafunzi, vitabu vya darasa na daftari.","assessment":"Majibu ya ufahamu, msamiati na muhtasari unaotumia ushahidi wa matini.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"10.3.1","themeId":10,"theme":"Kukabiliana na Ugaidi","strand":"Kuandika","title":"Insha za Masimulizi","persistedTitle":"Kukabiliana na Ugaidi — Insha za Masimulizi","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kupanga mawazo yanayohusu kukabiliana na ugaidi kwa kufuata muundo wa insha za masimulizi.","Kuandika matini yenye mpangilio mzuri, msamiati sahihi na maelezo yanayolenga msomaji.","Kukagua tahajia, uakifishaji na mtiririko wa mawazo na kuboresha rasimu baada ya maoni."],"inquiry":["Je, stadi ya insha za masimulizi hutusaidiaje kuelewa na kueleza kukabiliana na ugaidi?"],"experiences":["Panga mawazo kwa ramani fupi kabla ya kuandika insha za masimulizi kuhusu kukabiliana na ugaidi.","Andika rasimu, isome kwa mwenzako na ubaini sehemu zinazohitaji kufafanuliwa.","Wasilisha toleo lililoboreshwa ukizingatia lengo, hadhira na kanuni za uandishi."],"resources":"Vichocheo vya uandishi, daftari, kielelezo asilia na orodha ya ukaguzi.","assessment":"Rubriki ya muundo, ubunifu, usahihi wa lugha na uhariri.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"10.4.1","themeId":10,"theme":"Kukabiliana na Ugaidi","strand":"Sarufi","title":"Hali ya Masharti","persistedTitle":"Kukabiliana na Ugaidi — Hali ya Masharti","sourceLessons":3,"supportLessons":0,"lessons":3,"outcomes":["Kutambua matumizi ya hali ya masharti katika sentensi zinazohusiana na kukabiliana na ugaidi.","Kutunga sentensi sahihi kwa kuzingatia kanuni za hali ya masharti na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya hali ya masharti na kueleza sababu ya marekebisho."],"inquiry":["Je, hali ya masharti husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu kukabiliana na ugaidi na utambue hali ya masharti.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.1.1","themeId":11,"theme":"Ushuru","strand":"Kusikiliza na Kuzungumza","title":"Kujieleza kwa Ufasaha","persistedTitle":"Ushuru — Kujieleza kwa Ufasaha","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua namna ya kutumia kujieleza kwa ufasaha katika mazungumzo kuhusu ushuru.","Kueleza ujumbe wa mzungumzaji kwa matamshi yanayoeleweka na maneno yanayofaa muktadha wa ushuru.","Kushiriki mazungumzo au uwasilishaji mfupi kwa kusikiliza wengine na kutoa majibu yenye heshima."],"inquiry":["Je, stadi ya kujieleza kwa ufasaha hutusaidiaje kuelewa na kueleza ushuru?"],"experiences":["Sikiliza mazungumzo mafupi yaliyotungwa na mwalimu kuhusu ushuru na ubainishe kauli muhimu.","Fanya mazoezi ya kujieleza kwa ufasaha kwa jozi; mwezako atoe mrejesho wa heshima.","Wasilisha ujumbe wa sekunde 45 kwa darasa ukitumia msamiati unaohusiana na mada."],"resources":"Mazungumzo asilia, kadi za msamiati, sauti iliyorekodiwa na daftari.","assessment":"Orodha ya uchunguzi wa mazungumzo, matamshi, usikilizaji na majibu.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.2.1","themeId":11,"theme":"Ushuru","strand":"Kusoma","title":"Kusoma kwa Ufasaha","persistedTitle":"Ushuru — Kusoma kwa Ufasaha","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kusoma matini inayohusu ushuru kwa kutumia stadi ya kusoma kwa ufasaha.","Kubainisha msamiati, hoja kuu na maelezo muhimu yanayosaidia kuelewa matini.","Kujibu maswali na kueleza ujumbe wa matini kwa maneno yake mwenyewe na ushahidi wa alichosoma."],"inquiry":["Je, stadi ya kusoma kwa ufasaha hutusaidiaje kuelewa na kueleza ushuru?"],"experiences":["Soma kifungu asilia kuhusu ushuru, tia alama kwenye msamiati muhimu na ueleze maana.","Jibu maswali matatu ya ufahamu na utoe sababu kutoka kwenye kifungu.","Toa muhtasari wa hoja kuu kwa maneno yako mwenyewe."],"resources":"Vifungu asilia, kamusi ya mwanafunzi, vitabu vya darasa na daftari.","assessment":"Majibu ya ufahamu, msamiati na muhtasari unaotumia ushahidi wa matini.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.3.1","themeId":11,"theme":"Ushuru","strand":"Kuandika","title":"Barua Rasmi","persistedTitle":"Ushuru — Barua Rasmi","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kupanga mawazo yanayohusu ushuru kwa kufuata muundo wa barua rasmi.","Kuandika matini yenye mpangilio mzuri, msamiati sahihi na maelezo yanayolenga msomaji.","Kukagua tahajia, uakifishaji na mtiririko wa mawazo na kuboresha rasimu baada ya maoni."],"inquiry":["Je, stadi ya barua rasmi hutusaidiaje kuelewa na kueleza ushuru?"],"experiences":["Panga mawazo kwa ramani fupi kabla ya kuandika barua rasmi kuhusu ushuru.","Andika rasimu, isome kwa mwenzako na ubaini sehemu zinazohitaji kufafanuliwa.","Wasilisha toleo lililoboreshwa ukizingatia lengo, hadhira na kanuni za uandishi."],"resources":"Vichocheo vya uandishi, daftari, kielelezo asilia na orodha ya ukaguzi.","assessment":"Rubriki ya muundo, ubunifu, usahihi wa lugha na uhariri.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.4.1","themeId":11,"theme":"Ushuru","strand":"Sarufi","title":"Ukanusho wa Maneno","persistedTitle":"Ushuru — Ukanusho wa Maneno","sourceLessons":2,"supportLessons":1,"lessons":3,"outcomes":["Kutambua matumizi ya ukanusho wa maneno katika sentensi zinazohusiana na ushuru.","Kutunga sentensi sahihi kwa kuzingatia kanuni za ukanusho wa maneno na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya ukanusho wa maneno na kueleza sababu ya marekebisho."],"inquiry":["Je, ukanusho wa maneno husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu ushuru na utambue ukanusho wa maneno.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.4.2","themeId":11,"theme":"Ushuru","strand":"Sarufi","title":"Ukubwa na Udogo wa Nomino","persistedTitle":"Ushuru — Ukubwa na Udogo wa Nomino (2)","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya ukubwa na udogo wa nomino katika sentensi zinazohusiana na ushuru.","Kutunga sentensi sahihi kwa kuzingatia kanuni za ukubwa na udogo wa nomino na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya ukubwa na udogo wa nomino na kueleza sababu ya marekebisho."],"inquiry":["Je, ukubwa na udogo wa nomino husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu ushuru na utambue ukubwa na udogo wa nomino.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."},{"id":"11.4.3","themeId":11,"theme":"Ushuru","strand":"Sarufi","title":"Udogo wa Nomino","persistedTitle":"Ushuru — Udogo wa Nomino (3)","sourceLessons":2,"supportLessons":0,"lessons":2,"outcomes":["Kutambua matumizi ya udogo wa nomino katika sentensi zinazohusiana na ushuru.","Kutunga sentensi sahihi kwa kuzingatia kanuni za udogo wa nomino na upatanisho wa kisarufi.","Kurekebisha makosa ya matumizi ya udogo wa nomino na kueleza sababu ya marekebisho."],"inquiry":["Je, udogo wa nomino husaidiaje kuleta maana sahihi katika sentensi?"],"experiences":["Chunguza sentensi halisi zilizotungwa darasani kuhusu ushuru na utambue udogo wa nomino.","Unda mifano miwili sahihi na linganisha tofauti yake na sentensi yenye kosa.","Sahihisha sentensi na ueleze kanuni ya sarufi iliyotumika."],"resources":"Kadi za sentensi, daftari, mifano asilia na kamusi.","assessment":"Utambuzi wa kanuni, mifano sahihi na usahihishaji wa sentensi.","competencies":"Mawasiliano na ushirikiano, ubunifu, kufikiri kwa kina na kujiamini."}]'::jsonb) unit;
do $preflight$
begin
 if (select count(*) from _vs_grade6_sw_catalog)<>53
  or (select sum((unit->>'sourceLessons')::integer) from _vs_grade6_sw_catalog)<>115
  or (select sum((unit->>'lessons')::integer) from _vs_grade6_sw_catalog)<>120
  or (select sum((unit->>'supportLessons')::integer) from _vs_grade6_sw_catalog)<>5
  or (select count(distinct unit->>'strand') from _vs_grade6_sw_catalog)<>4
  or (select count(distinct unit->>'themeId') from _vs_grade6_sw_catalog)<>11
 then raise exception 'GRADE6_KISWAHILI_SOURCE_OR_PACING_MISMATCH'; end if;
 if (select count(*) from public.subjects where name='Kiswahili' and school_id is null and global_subject_id is null)<>1
 then raise exception 'GRADE6_KISWAHILI_CANONICAL_SUBJECT_MISSING'; end if;
 if exists(
   select 1 from _vs_grade6_sw_catalog t join public.subjects sub
     on sub.name='Kiswahili' and sub.school_id is null and sub.global_subject_id is null
   join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 6'
     and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'persistedTitle'
   where s.source_ref is not null and s.source_ref<>t.source_ref
 ) then raise exception 'GRADE6_KISWAHILI_CONFLICTING_EXISTING_SOURCE'; end if;
end;$preflight$;

insert into public.cbc_strands
(subject_id,grade,name,sub_strand,strand_order,sub_strand_order,key_inquiry_questions,suggested_experiences,source_ref)
select sub.id,'Grade 6',t.unit->>'strand',t.unit->>'persistedTitle',
 (t.unit->>'themeId')::integer,
 (split_part(t.unit->>'id','.',2)::integer*10+split_part(t.unit->>'id','.',3)::integer),
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences')),t.source_ref
from _vs_grade6_sw_catalog t
join public.subjects sub on sub.name='Kiswahili' and sub.school_id is null and sub.global_subject_id is null
on conflict(subject_id,grade,name,sub_strand) do nothing;

insert into public.grade6_kiswahili_reader_bindings
(source_ref,sub_strand_id,source_url,source_version,key_inquiry_questions,suggested_experiences,source_suggested_lessons,vibeschool_review_lessons)
select t.source_ref,s.id,
 'https://kicd.ac.ke/wp-content/uploads/2024/10/LATEST-6.8.2024-KISWAHILI-GRADE-6-Revised.pdf','KICD revised 2024; VibeSchool original outcomes',
 array(select jsonb_array_elements_text(t.unit->'inquiry')),
 array(select jsonb_array_elements_text(t.unit->'experiences')),
 (t.unit->>'sourceLessons')::integer,(t.unit->>'supportLessons')::integer
from _vs_grade6_sw_catalog t
join public.subjects sub on sub.name='Kiswahili' and sub.school_id is null and sub.global_subject_id is null
join public.cbc_strands s on s.subject_id=sub.id and s.grade='Grade 6'
 and s.name=t.unit->>'strand' and s.sub_strand=t.unit->>'persistedTitle'
on conflict(source_ref) do nothing;

insert into public.curriculum_unit_guidance
(sub_strand_id,suggested_lessons,learning_resources,assessment_methods,competencies,safety_notes,content_status)
select b.sub_strand_id,(t.unit->>'lessons')::integer,
 t.unit->>'resources',t.unit->>'assessment',t.unit->>'competencies',
 'Vifaa na kazi za umri husika; usalama na usimamizi wa mwalimu hasa katika mada nyeti.','active'
from _vs_grade6_sw_catalog t
join public.grade6_kiswahili_reader_bindings b on b.source_ref=t.source_ref
on conflict(sub_strand_id) do nothing;

insert into public.curriculum_learning_outcomes
(sub_strand_id,outcome_text,outcome_code,source_type,source_ref,status)
select b.sub_strand_id,o.text,
 'VS-G6-SW-'||(t.unit->>'id')||'-'||o.ordinality,
 'creator_claimed',t.source_ref||'/'||o.ordinality,'active'
from _vs_grade6_sw_catalog t
join public.grade6_kiswahili_reader_bindings b on b.source_ref=t.source_ref
cross join lateral jsonb_array_elements_text(t.unit->'outcomes') with ordinality as o(text,ordinality)
where not exists(select 1 from public.curriculum_learning_outcomes x where x.source_ref=t.source_ref||'/'||o.ordinality);

drop policy if exists grade6_kiswahili_original_outcomes_read on public.curriculum_learning_outcomes;
create policy grade6_kiswahili_original_outcomes_read on public.curriculum_learning_outcomes
 for select to authenticated using(
 status='active' and source_type='creator_claimed' and created_by is null
 and source_ref like 'VS-CUR-G06-SW-2026#%'
 );
drop policy if exists grade6_kiswahili_guidance_read on public.curriculum_unit_guidance;
create policy grade6_kiswahili_guidance_read on public.curriculum_unit_guidance
 for select to authenticated using(
  content_status='active' and exists (
   select 1 from public.grade6_kiswahili_reader_bindings b
   where b.sub_strand_id=curriculum_unit_guidance.sub_strand_id and b.status='active'
  )
 );
do $verify$
begin
 if (select count(*) from public.grade6_kiswahili_reader_bindings where status='active' and source_ref like 'VS-CUR-G06-SW-2026#%')<>53
  or (select sum(source_suggested_lessons) from public.grade6_kiswahili_reader_bindings where source_ref like 'VS-CUR-G06-SW-2026#%')<>115
  or (select sum(vibeschool_review_lessons) from public.grade6_kiswahili_reader_bindings where source_ref like 'VS-CUR-G06-SW-2026#%')<>5
  or (select sum(g.suggested_lessons) from public.grade6_kiswahili_reader_bindings b join public.curriculum_unit_guidance g on g.sub_strand_id=b.sub_strand_id where b.source_ref like 'VS-CUR-G06-SW-2026#%')<>120
  or (select count(*) from public.curriculum_learning_outcomes where source_ref like 'VS-CUR-G06-SW-2026#%' and status='active')<>159
 then raise exception 'GRADE6_KISWAHILI_PERSISTENCE_INCOMPLETE';end if;
end;$verify$;

-- This is the existing canonical invoker function, extended without losing the
-- Grade 1, Grade 4, Grade 6 English/Maths and Grade 8 authorisation paths.
CREATE OR REPLACE FUNCTION public.commit_mapped_scheme_lesson(p_class_id uuid, p_subject_id uuid, p_academic_term_id uuid, p_week integer, p_sub_strand_id uuid, p_outcome_ids uuid[])
 RETURNS scheme_of_work
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_unit public.cbc_strands%rowtype;
  v_guide public.curriculum_unit_guidance%rowtype;
  v_global_subject uuid;
  v_grade text;
  v_count integer;
  v_distinct integer;
  v_objectives text;
  v_first uuid;
  v_scheme public.scheme_of_work%rowtype;
  v_saved public.scheme_of_work%rowtype;
  v_reader_ref text;
  v_reader_inquiry text[];
  v_reader_experiences text[];
begin
  if (select auth.uid()) is null then raise exception 'SCHEME_AUTH_REQUIRED'; end if;
  if p_outcome_ids is null or cardinality(p_outcome_ids) not between 1 and 12 then
    raise exception 'SCHEME_OUTCOME_SELECTION_REQUIRED';
  end if;
  select count(distinct x) into v_distinct from unnest(p_outcome_ids) as x;
  if v_distinct<>cardinality(p_outcome_ids) then
    raise exception 'SCHEME_DUPLICATE_OUTCOMES';
  end if;

  -- Reuse Creative Activities source refs, or the audited VibeSchool reader
  -- binding for Mathematics/English. Legacy placeholders keep their original
  -- source_ref and identity; no official KICD promotion happens here.
  select * into v_unit from public.cbc_strands s
  where s.id=p_sub_strand_id and (
      (s.grade='Grade 1' and
        (s.source_ref like 'VS-CUR-G01-CA-2026#%'
         or exists (select 1 from public.grade1_curriculum_reader_bindings b
                    where b.sub_strand_id=s.id and b.status='active')))
      or (s.grade='Grade 8' and exists
        (select 1 from public.grade8_mathematics_reader_bindings b
         where b.sub_strand_id=s.id and b.status='active'))
      or (s.grade='Grade 8' and exists
        (select 1 from public.grade8_english_reader_bindings b
         where b.sub_strand_id=s.id and b.status='active'))
      or (s.grade='Grade 6' and exists
        (select 1 from public.grade6_english_reader_bindings b
         where b.sub_strand_id=s.id and b.status='active'))
      or (s.grade='Grade 6' and exists
        (select 1 from public.grade6_mathematics_reader_bindings b
         where b.sub_strand_id=s.id and b.status='active'))
      or (s.grade='Grade 6' and exists
        (select 1 from public.grade6_kiswahili_reader_bindings b
         where b.sub_strand_id=s.id and b.status='active'))
    );
  if not found then
    select * into v_unit from public.cbc_strands s
    where s.id=p_sub_strand_id and s.grade='Grade 4'
      and exists (select 1 from public.grade4_mathematics_reader_bindings b
                  where b.sub_strand_id=s.id and b.status='active');
  end if;
  if not found then
    select * into v_unit from public.cbc_strands s
    where s.id=p_sub_strand_id and s.grade='Grade 4'
      and exists(select 1 from public.grade4_english_reader_bindings b
                 where b.sub_strand_id=s.id and b.status='active');
  end if;
  if not found then raise exception 'SCHEME_CURRICULUM_SUBSTRAND_NOT_FOUND'; end if;

  select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
    into v_reader_ref,v_reader_inquiry,v_reader_experiences
  from public.grade1_curriculum_reader_bindings b
  where b.sub_strand_id=v_unit.id and b.status='active';
  if not found then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade8_mathematics_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade8_english_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade6_english_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade6_mathematics_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade4_mathematics_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade4_english_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    select b.source_ref,b.key_inquiry_questions,b.suggested_experiences
      into v_reader_ref,v_reader_inquiry,v_reader_experiences
    from public.grade6_kiswahili_reader_bindings b
    where b.sub_strand_id=v_unit.id and b.status='active';
  end if;
  if v_reader_ref is null then
    v_reader_ref:=v_unit.source_ref;
    v_reader_inquiry:=v_unit.key_inquiry_questions;
    v_reader_experiences:=v_unit.suggested_experiences;
  end if;
  select * into v_guide from public.curriculum_unit_guidance
    where sub_strand_id=v_unit.id and content_status='active';
  if not found then raise exception 'SCHEME_CURRICULUM_NOT_ACTIVE'; end if;

  select case when s.school_id is null then s.id else s.global_subject_id end
    into v_global_subject
  from public.subjects s where s.id=p_subject_id;
  select c.name into v_grade from public.classes c where c.id=p_class_id;
  if v_global_subject is distinct from v_unit.subject_id
    or lower(btrim(coalesce(v_grade,'')))<>lower(v_unit.grade)
  then raise exception 'SCHEME_CURRICULUM_IDENTITY_MISMATCH'; end if;

  select count(*),string_agg(o.outcome_text,E'\n' order by array_position(p_outcome_ids,o.id))
    into v_count,v_objectives
  from public.curriculum_learning_outcomes o
  where o.id=any(p_outcome_ids) and o.sub_strand_id=v_unit.id
    and o.status='active' and o.source_type='creator_claimed'
    and o.source_ref like v_reader_ref||'/%';
  if v_count<>cardinality(p_outcome_ids) then
    raise exception 'SCHEME_CURRICULUM_OUTCOME_MISMATCH'; end if;

  v_first:=p_outcome_ids[1];
  v_scheme:=public.commit_custom_scheme_item(
    p_class_id,p_subject_id,p_academic_term_id,p_week,v_unit.sub_strand,v_unit.name,null,null
  );
  update public.scheme_of_work set
      sub_strand_id=v_unit.id,
      sub_strand=v_unit.sub_strand,
      objectives=v_objectives,
      curriculum_outcome_id=v_first,
      key_inquiry_question=array_to_string(v_reader_inquiry,'; '),
      learning_experiences=array_to_string(v_reader_experiences,E'\n'),
      learning_resources=v_guide.learning_resources,
      assessment_methods=v_guide.assessment_methods,
      reference=v_reader_ref||case when v_unit.grade in ('Grade 8','Grade 6')
       then ' (KICD 2024 structure; independently authored VibeSchool teaching outcomes)'
       else ' (VibeSchool-authored; KICD reconciliation pending)' end
  where id=v_scheme.id and teacher_id=auth.uid()
  returning * into v_saved;
  if v_saved.id is null then raise exception 'SCHEME_LESSON_LINK_FAILED'; end if;

  insert into public.scheme_lesson_outcomes(scheme_lesson_id,curriculum_outcome_id)
  select v_saved.id,unnest(p_outcome_ids);
  return v_saved;
end;
$function$;

revoke all on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) from public,anon;
grant execute on function public.commit_mapped_scheme_lesson(uuid,uuid,uuid,integer,uuid,uuid[]) to authenticated;
commit;
